"use client";

import { useId, useRef, useState } from "react";
import type { CSSProperties, KeyboardEvent, ReactNode } from "react";
import { motion, useReducedMotion } from "motion/react";
import { Check, FileSpreadsheet, FileText, Image as ImageIcon, LayoutDashboard, ListChecks, Paperclip, Users } from "lucide-react";
import { motionTokens } from "@/lib/motion-tokens";
import { people } from "@/lib/media";
import styles from "./card-folder.module.css";

export interface FolderCard {
  /** Unique id, used as the value. */
  id: string;
  /** Text on the card's tab. */
  label: string;
  /** Small icon before the label. */
  icon?: ReactNode;
  /** What the card shows when it is in front. */
  content: ReactNode;
}

export interface CardFolderProps {
  /** The cards, in tab order. Defaults to a sample project folder. */
  cards?: FolderCard[];
  /** Id of the card in front. Pass it with `onValueChange` to control it. */
  value?: string;
  /** Id of the card that starts in front when uncontrolled. Defaults to the first card. */
  defaultValue?: string;
  /** Called with the id of the card whose tab was picked. */
  onValueChange?: (id: string) => void;
  /** Height of a card body in px. Every card shares it, so the folder never changes size. */
  height?: number;
  /** Accessible name of the tab list. */
  label?: string;
  /** Extra class for the folder. */
  className?: string;
}

/** How far each card behind the front one rises and shrinks. */
const STEP = 12;
const SHRINK = 0.035;
/** How far a picked card is pulled up before it drops in front. */
const LIFT = 58;

/** A folder of index cards: picking a tab pulls that card up out of the pile and drops it in front, while the others settle behind it. */
export function CardFolder({ cards = sampleCards, value, defaultValue, onValueChange, height = 296, label = "Project folder", className }: CardFolderProps) {
  const reduceMotion = useReducedMotion();
  const uid = useId();
  const [internal, setInternal] = useState(defaultValue ?? cards[0]?.id ?? "");
  const front = value ?? internal;
  // Pile order, front first. The front card comes from `value`; the rest keep the order in which they were last used.
  const [history, setHistory] = useState<string[]>(() => cards.map(card => card.id));
  const [lifting, setLifting] = useState<string | null>(null);
  const tabs = useRef(new Map<string, HTMLButtonElement>());
  // While a card is being pulled up, the pile still shows the old order; it changes when the card lands.
  const landed = lifting ? history : [front, ...history.filter(id => id !== front)];
  const order = [...landed.filter(id => cards.some(card => card.id === id)), ...cards.map(card => card.id).filter(id => !landed.includes(id))];

  const select = (id: string) => {
    if (id === front) return;
    setHistory(order);
    if (!reduceMotion) setLifting(id);
    if (value === undefined) setInternal(id);
    onValueChange?.(id);
  };
  const land = (id: string) => { if (lifting === id) setLifting(null); };

  const onKeyDown = (event: KeyboardEvent, index: number) => {
    const last = cards.length - 1;
    const next = event.key === "ArrowRight" ? (index === last ? 0 : index + 1) : event.key === "ArrowLeft" ? (index === 0 ? last : index - 1) : event.key === "Home" ? 0 : event.key === "End" ? last : -1;
    const target = cards[next];
    if (!target) return;
    event.preventDefault();
    tabs.current.get(target.id)?.focus();
    select(target.id);
  };

  return (
    <div className={[styles.folder, className].filter(Boolean).join(" ")} style={{ "--count": cards.length, "--body": `${height}px`, "--rise": `${(cards.length - 1) * STEP}px` } as CSSProperties}>
      <div role="tablist" aria-label={label} aria-owns={cards.map(card => `${uid}-tab-${card.id}`).join(" ")} />
      <div className={styles.pile}>
        {cards.map((card, index) => {
          const depth = Math.max(0, order.indexOf(card.id));
          const isFront = card.id === front;
          const rising = lifting === card.id;
          const rest = { y: -depth * STEP, scale: 1 - depth * SHRINK };
          // The card leaving the front keeps its content until the picked one has landed on top of it.
          const shown = lifting ? depth === 0 || rising : isFront;
          return (
            <motion.div
              key={card.id}
              className={styles.card}
              data-front={isFront}
              data-shown={shown}
              data-depth={depth}
              style={{ zIndex: cards.length - depth, "--index": index, "--depth": depth } as CSSProperties}
              initial={reduceMotion ? false : { opacity: 0, y: 36, scale: rest.scale }}
              animate={rising ? { opacity: 1, y: rest.y - LIFT, scale: rest.scale + 0.02 } : { opacity: 1, ...rest }}
              transition={reduceMotion ? { duration: 0 } : rising ? { duration: 0.17, ease: motionTokens.ease.standard } : { type: "spring", visualDuration: 0.4, bounce: isFront ? 0.22 : 0, delay: lifting ? 0 : undefined }}
              onAnimationComplete={() => land(card.id)}
            >
              <button
                ref={node => { if (node) tabs.current.set(card.id, node); else tabs.current.delete(card.id); }}
                type="button"
                role="tab"
                id={`${uid}-tab-${card.id}`}
                className={styles.tab}
                aria-selected={isFront}
                aria-controls={`${uid}-panel-${card.id}`}
                tabIndex={isFront ? 0 : -1}
                onClick={() => select(card.id)}
                onKeyDown={event => onKeyDown(event, index)}
              >
                <span className={styles.marker} aria-hidden="true" />
                {card.icon ? <span className={styles.tabIcon} aria-hidden="true">{card.icon}</span> : null}
                <span className={styles.tabLabel}>{card.label}</span>
              </button>
              <div role="tabpanel" id={`${uid}-panel-${card.id}`} aria-labelledby={`${uid}-tab-${card.id}`} className={styles.body} inert={!isFront} aria-hidden={!isFront}>
                <div className={styles.content}>{card.content}</div>
              </div>
            </motion.div>
          );
        })}
      </div>
    </div>
  );
}

const TASKS = [
  { text: "Lock the launch date with marketing", done: true },
  { text: "Record the product walkthrough", done: true },
  { text: "Write the migration guide", done: false },
  { text: "Send the beta invite to 40 teams", done: false },
];
const FILES = [
  { icon: <FileText size={15} />, name: "Launch brief.md", size: "18 KB" },
  { icon: <FileSpreadsheet size={15} />, name: "Pricing model.xlsx", size: "240 KB" },
  { icon: <ImageIcon size={15} />, name: "Hero shots.zip", size: "36 MB" },
  { icon: <Paperclip size={15} />, name: "Press kit.pdf", size: "4.2 MB" },
];

const sampleCards: FolderCard[] = [
  {
    id: "overview", label: "Overview", icon: <LayoutDashboard size={14} />,
    content: (
      <>
        <p className={styles.kicker}>Atlas 2.0 launch</p>
        <p className={styles.lead}>Two of four milestones are done and the beta opens on March 12.</p>
        <div className={styles.meter} role="img" aria-label="Progress: 62 percent"><span style={{ width: "62%" }} /></div>
        <dl className={styles.stats}>
          <div><dt>Progress</dt><dd>62%</dd></div>
          <div><dt>Open tasks</dt><dd>9</dd></div>
          <div><dt>Days left</dt><dd>21</dd></div>
        </dl>
      </>
    ),
  },
  {
    id: "tasks", label: "Tasks", icon: <ListChecks size={14} />,
    content: (
      <>
        <p className={styles.kicker}>This week</p>
        <ul className={styles.rows}>
          {TASKS.map(task => (
            <li key={task.text} data-done={task.done}><span className={styles.box} aria-hidden="true">{task.done ? <Check size={12} strokeWidth={3} /> : null}</span><span>{task.text}</span><span className={styles.srOnly}>{task.done ? "(done)" : "(open)"}</span></li>
          ))}
        </ul>
      </>
    ),
  },
  {
    id: "files", label: "Files", icon: <Paperclip size={14} />,
    content: (
      <>
        <p className={styles.kicker}>Recently added</p>
        <ul className={styles.rows}>
          {FILES.map(file => <li key={file.name}><span className={styles.fileIcon} aria-hidden="true">{file.icon}</span><span>{file.name}</span><span className={styles.aside}>{file.size}</span></li>)}
        </ul>
      </>
    ),
  },
  {
    id: "team", label: "Team", icon: <Users size={14} />,
    content: (
      <>
        <p className={styles.kicker}>Working on it</p>
        <ul className={styles.rows}>
          {people.slice(0, 4).map(member => <li key={member.id}><img className={styles.face} src={member.src} alt="" /><span>{member.name}</span><span className={styles.aside}>{member.role}</span></li>)}
        </ul>
      </>
    ),
  },
];

/** Ready preview: the sample project folder on a quiet stage. */
export function CardFolderPreview() {
  return (
    <section className={styles.preview} aria-label="Card folder">
      <CardFolder />
    </section>
  );
}

export default CardFolderPreview;

.folder {
  /* Cards further back fade toward this tone: a step darker in the dark theme, a step greyer in the light one. */
  --far: var(--surface-muted);
  --tab: 38px;
  container: folder / inline-size; width: min(30rem, 100%); padding-top: calc(var(--rise) + 4px); color: var(--foreground); font-family: var(--font-body); letter-spacing: var(--tracking-body);
}
:global(:root[data-theme="dark"]) .folder { --far: var(--background); }
.folder *, .folder *::before, .folder *::after { box-sizing: border-box; }
.srOnly { position: absolute; width: 1px; height: 1px; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

.pile { position: relative; height: calc(var(--tab) + var(--body)); }
/* Every card fills the pile and is placed by transforms. The tab's slot along the top edge is fixed by tab order, so tabs never swap places. */
.card { --tone: color-mix(in oklab, var(--surface-raised), var(--far) min(100%, calc(var(--depth) * 36%))); position: absolute; inset: 0; transform-origin: 50% 0; will-change: transform; pointer-events: none; }
.tab {
  position: absolute; top: 0; left: calc(var(--radius-panel) + var(--index) * (100% - 2 * var(--radius-panel)) / var(--count)); z-index: 1; display: flex; width: calc((100% - 2 * var(--radius-panel)) / var(--count) - 4px); height: calc(var(--tab) + 1px); align-items: center; justify-content: center; gap: 6px; padding: 4px var(--space-2) 0;
  border: 1px solid var(--border); border-bottom: 0; border-radius: var(--radius-control) var(--radius-control) 0 0; background: var(--tone); color: var(--text-muted); font: inherit; font-size: var(--text-sm); font-weight: 500; cursor: pointer; pointer-events: auto; -webkit-tap-highlight-color: transparent;
  transition: background-color var(--duration-standard) var(--ease-standard), color var(--duration-fast) var(--ease-standard);
}
.tab:hover { color: var(--foreground); }
/* The keyboard outline sits inside the tab, so it does not cut across the card below. */
.tab { --focus-outline-offset: -4px; }
.tab[aria-selected="true"] { color: var(--foreground); }
.tabIcon { display: grid; flex: none; place-items: center; }
.tabLabel { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
/* The front card's tab carries the accent as a short bar that grows in along its top edge. */
.marker { position: absolute; top: 5px; left: calc(50% - 9px); width: 18px; height: 3px; border-radius: var(--radius-pill); background: var(--accent-strong); opacity: 0; transform: scaleX(0); transition: transform var(--duration-spring) var(--ease-spring), opacity var(--duration-fast) var(--ease-standard); }
.tab[aria-selected="true"] .marker { opacity: 1; transform: scaleX(1); }

.body { position: absolute; inset: var(--tab) 0 0; overflow: hidden; border: 1px solid var(--border); border-radius: var(--radius-panel); background: var(--tone); box-shadow: var(--shadow-raised); pointer-events: auto; transition: background-color var(--duration-standard) var(--ease-standard), box-shadow var(--duration-standard) var(--ease-standard); }
.card[data-front="true"] .body { box-shadow: var(--shadow-floating); }
.content { display: grid; align-content: start; gap: var(--space-3); height: 100%; padding: var(--space-6); transition: opacity var(--duration-standard) var(--ease-standard); }
.card[data-shown="false"] .content { opacity: 0; }

/* Sample content. */
.kicker { margin: 0; color: var(--text-muted); font-size: var(--text-xs); font-weight: 500; letter-spacing: .04em; text-transform: uppercase; }
.lead { max-width: 30ch; margin: 0; font-family: var(--font-display); font-size: var(--text-xl); font-weight: 500; letter-spacing: var(--tracking-display); line-height: 1.2; text-wrap: balance; }
.meter { height: 8px; margin-top: var(--space-2); overflow: hidden; border-radius: var(--radius-pill); background: var(--surface-muted); }
.meter span { display: block; height: 100%; border-radius: inherit; background: var(--accent); }
.stats { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--space-3); margin: var(--space-2) 0 0; }
.stats dt { color: var(--text-muted); font-size: var(--text-xs); }
.stats dd { margin: 2px 0 0; font-family: var(--font-display); font-size: var(--text-xl); font-weight: 500; font-variant-numeric: tabular-nums; letter-spacing: var(--tracking-display); }
.rows { display: grid; margin: 0; padding: 0; list-style: none; }
.rows li { display: flex; min-height: 46px; align-items: center; gap: var(--space-3); border-top: 1px solid var(--border-subtle); font-size: var(--text-sm); }
.rows li:first-child { border-top: 0; }
.rows li > span:nth-child(2) { min-width: 0; flex: 1 1 auto; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.rows li[data-done="true"] > span:nth-child(2) { color: var(--text-muted); text-decoration: line-through; }
.box { display: grid; width: 18px; height: 18px; flex: none; place-items: center; border: 1.5px solid var(--border-strong); border-radius: 6px; }
.rows li[data-done="true"] .box { border-color: var(--control-on); background: var(--control-on); color: var(--control-glyph); }
.fileIcon { display: grid; width: 30px; height: 30px; flex: none; place-items: center; border-radius: var(--radius-pill); background: var(--surface-muted); color: var(--text-secondary); }
.face { width: 30px; height: 30px; flex: none; border-radius: var(--radius-pill); object-fit: cover; }
.aside { flex: none; color: var(--text-muted); font-size: var(--text-xs); font-variant-numeric: tabular-nums; }

.preview { display: grid; min-height: 560px; flex: 1 1 auto; place-items: center; padding: var(--space-8) var(--space-4); background: var(--background); }

@container folder (max-width: 26rem) { .tabIcon { display: none; } .content { padding: var(--space-5); } .tab { font-size: var(--text-xs); } }
@media (prefers-reduced-motion: reduce) { .tab, .marker, .body, .content { transition: none; } }

/**
 * Shared demo media. Files live in `public/media/` and are generated by `scripts/make-media.mjs`:
 * people are seeded gradient avatars (400 px squares), photos are abstract generated scenes. No third-party images.
 *
 * Paths start at `/media`. An app served from a subfolder sets `globalThis.__RYAN_UI_MEDIA__` (for example to
 * "./media") before the components load.
 */
const mediaRoot = ((globalThis as { __RYAN_UI_MEDIA__?: string }).__RYAN_UI_MEDIA__ ?? "/media").replace(/\/$/, "");

/** Resolves a path inside the media folder, such as `mediaUrl("people/emma-collins.svg")`. */
export const mediaUrl = (path: string) => `${mediaRoot}/${path.replace(/^\//, "")}`;

export interface MediaPerson {
  id: string;
  name: string;
  role?: string;
  src: string;
}

export interface MediaPhoto {
  id: string;
  alt: string;
  src: string;
  width: number;
  height: number;
}

